fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();

    // Since it's guaranteed that every pair sum is < 256,
    // all nums[i] < 256. We can bucket indices by value.
    let mut positions: Vec<Vec<usize>> = vec![Vec::new(); 256];
    for (i, &val) in nums.iter().enumerate() {
        // Safe to cast to usize because val < 256
        positions[val as usize].push(i);
    }

    // For each p in increasing order, look for the smallest q > p
    // such that nums[p] + nums[q] == target.
    for p in 0..n {
        let a = nums[p];
        if a > target {
            // can't form target if a is already bigger
            continue;
        }
        let c = (target - a) as usize;
        if c >= 256 {
            // no element can equal c if c >= 256
            continue;
        }
        let vec_c = &positions[c];
        // find the smallest index in vec_c that is > p via binary search
        // on the sorted list of indices
        if let Err(idx) = vec_c.binary_search(&(p + 1)) {
            // Err(idx) is the insertion point for p+1,
            // which is the first element > p
            if idx < vec_c.len() {
                let q = vec_c[idx];
                return (p, q);
            }
        } else {
            // Ok(idx): exact match on p+1 means that is our q
            let idx = vec_c.binary_search(&(p + 1)).unwrap();
            let q = vec_c[idx];
            return (p, q);
        }
    }

    // According to the problem assumptions, there is always a valid pair.
    unreachable!("There is guaranteed to be at least one valid pair");
}

