    #[test]
    fn test_multiple_pairs() {
        let nums = vec![1, 2, 3, 4, 5];
        let target = 6;
        // pairs summing to 6 are (1,4) => indices (0,4), (1,3) => (1,3), (2,2) invalid
        // Lexicographically smallest is (0, 4).
        assert_eq!(two_sum(&nums, target), (0, 4));
    }

    #[test]
    fn test_edge_indices() {
        let nums = vec![0, 255, 128, 127, 129];
        let target = 255;
        // possible: (0,1)=255, (2,3)=255
        // lexicographically smallest is (0,1)
        assert_eq!(two_sum(&nums, target), (0, 1));
    }
